CREATE TABLE IF NOT EXISTS tochat_turns ( user_id INTEGER NOT NULL, message_id TEXT NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('chat','work')), fingerprint TEXT NOT NULL, counted INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'new', rounds INTEGER NOT NULL DEFAULT 0, current_request TEXT, expected_tools TEXT, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,message_id) );
CREATE INDEX IF NOT EXISTS tochat_turn_day ON tochat_turns(user_id,day,kind,counted);
CREATE TABLE IF NOT EXISTS tochat_requests ( user_id INTEGER NOT NULL, request_id TEXT NOT NULL, message_id TEXT NOT NULL, day TEXT NOT NULL, week TEXT NOT NULL, kind TEXT NOT NULL, charged INTEGER NOT NULL CHECK(charged >= 0), status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, finished_at INTEGER, PRIMARY KEY(user_id,request_id) );
CREATE INDEX IF NOT EXISTS tochat_request_day ON tochat_requests(user_id,day,kind);
CREATE INDEX IF NOT EXISTS tochat_request_week ON tochat_requests(user_id,week,kind);
CREATE TABLE IF NOT EXISTS user_subscription (user_id INTEGER PRIMARY KEY, plan_id TEXT NOT NULL, expires_at INTEGER NOT NULL, five_hour_limit INTEGER NOT NULL DEFAULT 0, week_limit INTEGER NOT NULL DEFAULT 0, month_limit INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS usage_log (user_id INTEGER NOT NULL, request_id TEXT NOT NULL, model TEXT NOT NULL, feature TEXT NOT NULL, credit_micro INTEGER NOT NULL DEFAULT 0 CHECK(credit_micro>=0), held_micro INTEGER NOT NULL DEFAULT 0 CHECK(held_micro>=0), input_tokens INTEGER NOT NULL DEFAULT 0, cached_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', rate_version TEXT NOT NULL DEFAULT '2026-10-04', created_at INTEGER NOT NULL, finished_at INTEGER, PRIMARY KEY(user_id,request_id));
CREATE INDEX IF NOT EXISTS agent_usage_window ON usage_log(user_id,created_at);
CREATE TABLE IF NOT EXISTS subscription_checkout (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, plan_id TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, next_poll_at INTEGER NOT NULL DEFAULT 0, order_no TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX IF NOT EXISTS subscription_checkout_user ON subscription_checkout(user_id,created_at);
CREATE TABLE IF NOT EXISTS subscription_orders (order_no TEXT PRIMARY KEY, checkout_id TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, plan_id TEXT NOT NULL, months INTEGER NOT NULL, amount TEXT NOT NULL, created_at INTEGER NOT NULL);
DROP TRIGGER IF EXISTS tochat_turn_quota;
DROP TRIGGER IF EXISTS tochat_request_quota;
CREATE TRIGGER IF NOT EXISTS tochat_request_access BEFORE INSERT ON tochat_requests BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tochat_turns WHERE user_id=NEW.user_id AND message_id=NEW.message_id AND current_request=NEW.request_id AND state='active') THEN RAISE(ABORT,'TOCHAT_TURN_BUSY_OR_DONE') END; SELECT CASE WHEN (SELECT COUNT(*) FROM tochat_requests WHERE user_id=NEW.user_id AND status='pending') >= 2 THEN RAISE(ABORT,'TOCHAT_CONCURRENT_LIMIT') END; END;
CREATE TRIGGER IF NOT EXISTS agent_credit_quota BEFORE INSERT ON usage_log BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM user_subscription WHERE user_id=NEW.user_id AND expires_at>NEW.created_at) THEN RAISE(ABORT,'AGENT_SUBSCRIPTION_REQUIRED') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM user_subscription AS s WHERE s.user_id=NEW.user_id AND ((s.five_hour_limit>0 AND NEW.credit_micro+NEW.held_micro+(SELECT COALESCE(SUM(credit_micro+held_micro),0) FROM usage_log WHERE user_id=NEW.user_id AND created_at>NEW.created_at-18000000)>s.five_hour_limit) OR (s.week_limit>0 AND NEW.credit_micro+NEW.held_micro+(SELECT COALESCE(SUM(credit_micro+held_micro),0) FROM usage_log WHERE user_id=NEW.user_id AND created_at>NEW.created_at-604800000)>s.week_limit) OR (s.month_limit>0 AND NEW.credit_micro+NEW.held_micro+(SELECT COALESCE(SUM(credit_micro+held_micro),0) FROM usage_log WHERE user_id=NEW.user_id AND created_at>NEW.created_at-2592000000)>s.month_limit))) THEN RAISE(ABORT,'AGENT_CREDIT_LIMIT') END; END;
CREATE TRIGGER IF NOT EXISTS subscription_no_downgrade BEFORE UPDATE ON user_subscription WHEN OLD.expires_at>NEW.updated_at AND (CASE OLD.plan_id WHEN 'plus' THEN 1 WHEN 'pro' THEN 2 WHEN 'max5' THEN 3 WHEN 'max20' THEN 4 WHEN 'ultra' THEN 5 WHEN 'ultrax' THEN 6 END)>(CASE NEW.plan_id WHEN 'plus' THEN 1 WHEN 'pro' THEN 2 WHEN 'max5' THEN 3 WHEN 'max20' THEN 4 WHEN 'ultra' THEN 5 WHEN 'ultrax' THEN 6 END) BEGIN SELECT RAISE(ABORT,'SUBSCRIPTION_DOWNGRADE_BLOCKED'); END;
